using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "ConfigMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features", Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns active feature flags.")]
    public static string GetFeatureFlags()
    {
        var flags = new Dictionary<string, bool>
        {
            ["dark_mode"] = true,
            ["beta_api"] = false,
            ["caching"] = true
        };
        return JsonSerializer.Serialize(flags, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Checks whether a specific feature flag is enabled.")]
    public static string CheckFeature(
        [Description("The feature flag name to check (e.g., 'dark_mode')")] string featureName)
    {
        var flags = new Dictionary<string, bool>
        {
            ["dark_mode"] = true,
            ["beta_api"] = false,
            ["caching"] = true
        };

        if (flags.TryGetValue(featureName, out var enabled))
            return $"Feature '{featureName}' is {(enabled ? "enabled" : "disabled")}.";

        return $"Feature '{featureName}' not found. Available: {string.Join(", ", flags.Keys)}";
    }
}

